import React, { useState, useRef, useEffect } from 'react';
import { ChevronLeft, ChevronRight, ZoomIn, ZoomOut, Save, Target, Eraser, Loader2, Palette, Trash2, BoxSelect } from 'lucide-react';
import { useQuery, useMutation } from '@tanstack/react-query';
import apiClient from '../../api/client';

interface PointSelectorProps {
  projectId: string;
}

export const PointSelector: React.FC<PointSelectorProps> = ({ projectId }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [zoom, setZoom] = useState(1.0);
  const [mode, setMode] = useState<'points' | 'delete' | 'cluster' | 'colors'>('points');
  const [numClusters, setNumClusters] = useState(10);
  const [points, setPoints] = useState<any[]>([]);

  // Selection State
  const [isDragging, setIsDragging] = useState(false);
  const [selectionStart, setSelectionStart] = useState<{ x: number, y: number } | null>(null);
  const [selectionRect, setSelectionRect] = useState<{ x: number, y: number, w: number, h: number } | null>(null);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const { data: projectFiles, isLoading } = useQuery({
    queryKey: ['project-files', projectId],
    queryFn: async () => {
      const response = await apiClient.get(`/projects/${projectId}/files`);
      return response.data;
    }
  });

  const calibrationImages = projectFiles?.calibration_images || [];
  const currentImage = calibrationImages[currentIndex];

  const [blurAmount, setBlurAmount] = useState(0);
  const [pointColors, setPointColors] = useState<string[]>([]);

  useEffect(() => {
    // Reset points when changing image (in a real app, you'd fetch points for the image)
    if (currentImage?.points) {
      setPoints([...currentImage.points]);
    } else {
      setPoints([]);
    }
    setBlurAmount(0);
    setPointColors([]);
  }, [currentImage]);

  useEffect(() => {
    if (currentImage && canvasRef.current) {
      renderCanvas();
    }
  }, [currentImage, zoom, points, projectId, selectionRect, blurAmount]);

  const renderCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas || !currentImage) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    const apiBase = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000/api';
    const baseUrl = apiBase.replace(/\/api$/, '');

    const getFullUrl = (path?: string) => {
      if (!path) return '';
      if (path.startsWith('http')) return path;
      const normalizedPath = path.startsWith('/') ? path : `/${path}`;
      return `${baseUrl}${normalizedPath}`;
    };

    const rawUrl = currentImage.url || `/data/storage/projects/${projectId}/calibration_images/${currentImage.filename}`;
    const fullUrl = getFullUrl(rawUrl);

    img.src = fullUrl;

    img.onload = () => {
      canvas.width = img.width * zoom;
      canvas.height = img.height * zoom;
      ctx.scale(zoom, zoom);

      // Apply Blur
      ctx.filter = `blur(${blurAmount}px)`;
      ctx.drawImage(img, 0, 0);
      ctx.filter = 'none'; // Reset for points

      drawPoints(ctx, zoom);
      drawSelection(ctx);
    };
  };

  const drawPoints = (ctx: CanvasRenderingContext2D, currentZoom: number) => {
    const newColors: string[] = [];

    points.forEach((p) => {
      let fillStyle = 'red'; // Default if sampling fails
      try {
        const px = Math.floor(p.x * currentZoom);
        const py = Math.floor(p.y * currentZoom);

        if (px >= 0 && py >= 0 && px < ctx.canvas.width && py < ctx.canvas.height) {
           const pixel = ctx.getImageData(px, py, 1, 1).data;
           fillStyle = `rgb(${pixel[0]}, ${pixel[1]}, ${pixel[2]})`;
        }
      } catch (e) {
        // Fallback for CORS or out of bounds
      }
      newColors.push(fillStyle);

      ctx.beginPath();
      ctx.arc(p.x, p.y, 5, 0, 2 * Math.PI);
      ctx.fillStyle = fillStyle;
      ctx.fill();

      ctx.strokeStyle = 'white';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.strokeStyle = 'rgba(0,0,0,0.5)';
      ctx.lineWidth = 0.5;
      ctx.stroke();
    });

    // Update state only if changed to avoid infinite loops
    if (JSON.stringify(newColors) !== JSON.stringify(pointColors)) {
      setPointColors(newColors);
    }
  };

  const getContrastColor = (rgbStr: string) => {
    if (!rgbStr || !rgbStr.startsWith('rgb')) return 'white';
    const match = rgbStr.match(/\d+/g);
    if (!match) return 'white';
    const [r, g, b] = match.map(Number);
    // Standard brightness formula
    const brightness = (r * 299 + g * 587 + b * 114) / 1000;
    return brightness > 128 ? 'black' : 'white';
  };


  const drawSelection = (ctx: CanvasRenderingContext2D) => {
    if (selectionRect) {
      ctx.strokeStyle = '#00ff00';
      ctx.lineWidth = 2 / zoom;
      ctx.setLineDash([5 / zoom, 3 / zoom]);
      ctx.strokeRect(selectionRect.x, selectionRect.y, selectionRect.w, selectionRect.h);
      ctx.setLineDash([]);
    }
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / zoom;
    const y = (e.clientY - rect.top) / zoom;

    if (mode === 'cluster' || mode === 'colors') {
      setIsDragging(true);
      setSelectionStart({ x, y });
      setSelectionRect({ x, y, w: 0, h: 0 });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / zoom;
    const y = (e.clientY - rect.top) / zoom;

    if (isDragging && selectionStart) {
      const w = x - selectionStart.x;
      const h = y - selectionStart.y;
      setSelectionRect({ x: selectionStart.x, y: selectionStart.y, w, h });
    }
  };

  const datasetMutation = useMutation({
    mutationFn: async (payload: any) => {
      const endpoint = mode === 'cluster' ? '/dataset/tools/cluster' : '/dataset/tools/colors';
      const res = await apiClient.post(endpoint, payload);
      return res.data;
    },
    onSuccess: (data) => {
      if (data.points) {
        setPoints(prev => [...prev, ...data.points]);
      }
    }
  });

  const savePointsMutation = useMutation({
    mutationFn: async () => {
      await apiClient.post(`/projects/${projectId}/dataset/save`, {
        filename: currentImage.filename,
        points: points
      });
      alert('Configuration saved.');
    }
  });

  const handleSave = () => {
    if (!currentImage) return;
    savePointsMutation.mutate();
  };

  const handleMouseUp = () => {
    if (isDragging && selectionRect && selectionStart) {
      setIsDragging(false);
      const rx = selectionRect.w < 0 ? selectionRect.x + selectionRect.w : selectionRect.x;
      const ry = selectionRect.h < 0 ? selectionRect.y + selectionRect.h : selectionRect.y;
      const rw = Math.abs(selectionRect.w);
      const rh = Math.abs(selectionRect.h);

      if (rw > 5 && rh > 5) {
        datasetMutation.mutate({
          project_id: projectId,
          filename: currentImage.filename,
          roi: [Math.floor(rx), Math.floor(ry), Math.floor(rx + rw), Math.floor(ry + rh)],
          k: numClusters
        });
      }
      setSelectionRect(null);
      setSelectionStart(null);
    }
  };

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (mode === 'cluster' || mode === 'colors') return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / zoom;
    const y = (e.clientY - rect.top) / zoom;

    if (mode === 'points') {
      setPoints([...points, { x, y }]);
    } else if (mode === 'delete') {
      setPoints(points.filter(p => Math.sqrt((p.x - x) ** 2 + (p.y - y) ** 2) > 10));
    }
  };

  const handleClearPoints = () => setPoints([]);
  const deletePoint = (index: number) => {
    setPoints(points.filter((_, i) => i !== index));
  };

  if (isLoading) return <div className="flex justify-center p-10"><Loader2 className="animate-spin text-green-600" /></div>;
  if (calibrationImages.length === 0) return <div className="text-center py-20 text-neutral-600 italic">No calibration images available for this project.</div>;

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between bg-neutral-900 border border-neutral-800 rounded-xl p-4 gap-4">

        {/* Tools Group */}
        <div className="flex items-center gap-4 flex-wrap">
          <div className="flex bg-neutral-950 border border-neutral-800 rounded-lg p-1">
            <button onClick={() => setMode('points')} className={`p-2 rounded-md transition-all ${mode === 'points' ? 'bg-green-600 text-white shadow-lg' : 'text-neutral-500 hover:text-white'}`} title="Add Points"><Target className="w-4 h-4" /></button>
            <button onClick={() => setMode('delete')} className={`p-2 rounded-md transition-all ${mode === 'delete' ? 'bg-red-600 text-white shadow-lg' : 'text-neutral-500 hover:text-white'}`} title="Delete Points"><Eraser className="w-4 h-4" /></button>
          </div>

          <div className="h-8 w-[1px] bg-neutral-800 mx-1 hidden sm:block" />

          {/* Blur Control */}
           <div className="flex bg-neutral-950 border border-neutral-800 rounded-lg px-3 py-1 items-center gap-2">
            <span className="text-[10px] text-neutral-500 uppercase font-bold">Blur:</span>
            <input 
              type="range" 
              min="0" 
              max="20" 
              value={blurAmount} 
              onChange={(e) => setBlurAmount(Number(e.target.value))}
              className="w-24 h-1 bg-neutral-800 rounded-lg appearance-none cursor-pointer accent-green-600"
            />
            <span className="text-[10px] text-neutral-400 font-mono w-4">{blurAmount}</span>
          </div>

          <div className="h-8 w-[1px] bg-neutral-800 mx-1 hidden sm:block" />

          {/* Advanced Selection Tools */}
          <div className="flex bg-neutral-950 border border-neutral-800 rounded-lg p-1 items-center">
            <button onClick={() => setMode('cluster')} className={`p-2 rounded-md transition-all flex items-center gap-2 ${mode === 'cluster' ? 'bg-blue-600 text-white shadow-lg' : 'text-neutral-500 hover:text-white'}`} title="Cluster Selection"><BoxSelect className="w-4 h-4" /><span className="text-xs font-bold hidden sm:inline">Cluster</span></button>
            {mode === 'cluster' && (
              <div className="flex items-center px-2 border-l border-neutral-800 ml-1 animate-in slide-in-from-left-2 fade-in">
                <span className="text-[10px] text-neutral-500 mr-2 uppercase font-bold">K:</span>
                <input type="number" value={numClusters} onChange={e => setNumClusters(Number(e.target.value))} className="w-12 bg-neutral-900 border border-neutral-800 rounded px-1 py-0.5 text-xs text-center" min={1} max={50} />
              </div>
            )}
            <div className="w-[1px] h-4 bg-neutral-800 mx-1" />
            <button onClick={() => setMode('colors')} className={`p-2 rounded-md transition-all flex items-center gap-2 ${mode === 'colors' ? 'bg-purple-600 text-white shadow-lg' : 'text-neutral-500 hover:text-white'}`} title="Get Unique Colors"><Palette className="w-4 h-4" /><span className="text-xs font-bold hidden sm:inline">Colors</span></button>
          </div>

          <div className="h-8 w-[1px] bg-neutral-800 mx-1 hidden sm:block" />

          {/* Zoom Controls */}
          <div className="flex bg-neutral-950 border border-neutral-800 rounded-lg p-1">
            <button onClick={() => setZoom(z => z * 1.2)} className="p-2 text-neutral-500 hover:text-white"><ZoomIn className="w-4 h-4" /></button>
            <button onClick={() => setZoom(z => z / 1.2)} className="p-2 text-neutral-500 hover:text-white"><ZoomOut className="w-4 h-4" /></button>
            <span className="px-3 flex items-center text-[10px] font-bold text-neutral-500 border-l border-neutral-800">{(zoom * 100).toFixed(0)}%</span>
          </div>
        </div>

        {/* Global Action Group */}
        <div className="flex items-center gap-3">
          <button onClick={handleClearPoints} className="p-2 text-neutral-400 hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-colors" title="Clear All Points"><Trash2 className="w-4 h-4" /></button>
          <div className="h-8 w-[1px] bg-neutral-800 mx-1" />
          <div className="flex gap-1">
            <button disabled={currentIndex === 0} onClick={() => setCurrentIndex(i => i - 1)} className="p-2 bg-neutral-950 border border-neutral-800 rounded-lg disabled:opacity-30 hover:border-neutral-600 transition-colors"><ChevronLeft className="w-4 h-4" /></button>
            <span className="text-xs font-mono text-neutral-500 self-center px-2">{currentIndex + 1} / {calibrationImages.length}</span>
            <button disabled={currentIndex === calibrationImages.length - 1} onClick={() => setCurrentIndex(i => i + 1)} className="p-2 bg-neutral-950 border border-neutral-800 rounded-lg disabled:opacity-30 hover:border-neutral-600 transition-colors"><ChevronRight className="w-4 h-4" /></button>
          </div>
          <button onClick={handleSave} disabled={savePointsMutation.isPending} className={`flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg text-sm font-bold shadow-lg shadow-green-900/20 transition-all ml-2 ${savePointsMutation.isPending ? 'opacity-70 cursor-wait' : ''}`}>{savePointsMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}{savePointsMutation.isPending ? 'SAVING...' : 'SAVE'}</button>
        </div>
      </div>

      {datasetMutation.isPending && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 bg-black/50 backdrop-blur rounded-full px-6 py-3 flex items-center gap-3 text-white border border-white/10">
          <Loader2 className="w-5 h-5 animate-spin" />
          <span className="text-xs font-bold tracking-widest">PROCESSING...</span>
        </div>
      )}

      {/* Main Content Grid: Canvas + Sidebar */}
      <div className="grid grid-cols-1 lg:grid-cols-[1fr_250px] gap-6">

        {/* Canvas Area */}
        <div className="bg-neutral-950 border border-neutral-800 rounded-2xl overflow-hidden relative group h-[600px]">
          <div
            ref={containerRef}
            className="w-full h-full overflow-auto flex items-start justify-start cursor-crosshair p-10 bg-[radial-gradient(#262626_1px,transparent_1px)] [background-size:24px_24px]"
          >
            <canvas
              ref={canvasRef}
              onClick={handleClick}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={() => { setIsDragging(false); setSelectionRect(null); }}
              className={`shadow-2xl border border-neutral-800 ${isDragging ? 'cursor-crosshair' : ''}`}
            />
          </div>
          <div className="absolute bottom-6 left-6 bg-neutral-900/80 backdrop-blur-md border border-neutral-800 rounded-lg px-4 py-2 text-xs font-mono text-neutral-400 opacity-0 group-hover:opacity-100 transition-opacity">
            {currentImage?.filename}
          </div>
        </div>

        {/* Side Panel: Points List */}
        <div className="bg-neutral-900/50 border border-neutral-800 rounded-xl p-4 flex flex-col h-[600px]">
          <h3 className="text-sm font-bold text-neutral-300 mb-4 flex items-center gap-2">
            <Target className="w-4 h-4 text-green-500" />
            Points List ({points.length})
          </h3>

          <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
            {points.length === 0 ? (
              <div className="text-center text-neutral-600 text-xs py-10 italic">No points selected</div>
            ) : (
              points.map((p, idx) => {
                const bgCol = pointColors[idx] || '#171717';
                const textCol = getContrastColor(bgCol);

                return (
                  <div key={idx} 
                       className="group flex items-center justify-between p-2 border border-neutral-800 rounded-lg hover:border-neutral-600 transition-colors"
                       style={{ backgroundColor: bgCol }}>
                    <div className="flex items-center gap-3">
                      <span className="text-xs font-mono w-5" style={{ color: textCol }}>#{idx + 1}</span>
                      <div className="flex flex-col">
                        <span className="text-[10px] font-mono" style={{ color: textCol }}>X: {Math.floor(p.x)}</span>
                        <span className="text-[10px] font-mono" style={{ color: textCol }}>Y: {Math.floor(p.y)}</span>
                      </div>
                    </div>
                    <button 
                      onClick={() => deletePoint(idx)}
                      className="p-1.5 rounded transition-colors opacity-0 group-hover:opacity-100 hover:bg-black/10"
                      style={{ color: textCol }}
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  </div>
                );
              })
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

